gNL(){return"\u0627\u062d\u0641\u0638 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0641\u064a \u062c\u0648\u062c\u0644 \u062f\u0631\u0627\u064a\u0641 \u0627\u0644\u062e\u0627\u0635 \u0628\u0643"},
