gOg(){return"\u0623\u0631\u0635\u062f\u0629 \u0646\u0642\u062f\u064a\u0629 \u0635\u063a\u064a\u0631\u0629 \u0644\u0644\u0625\u0646\u0641\u0627\u0642 \u0627\u0644\u064a\u0648\u0645\u064a \u0627\u0644\u0628\u0633\u064a\u0637"},
gNI(){return"\u062a\u062d\u0648\u064a\u0644 \u0628\u064a\u0646 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a"},
gNJ(){return"\u0646\u0642\u0644 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0628\u064a\u0646 \u0627\u0644\u0646\u0642\u062f \u0648\u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u0645\u0635\u0631\u0641\u064a\u0629 \u0648\u0627\u0644\u0646\u062b\u0631\u064a\u0629"},
